 auto catalog=std::make_shared<CommonCatalog>();CommonState initial;initial.identity.tick=7;ActorRecord actor;actor.id="person";actor.alive=false;initial.actors.insert(actor.id,actor);CommonStore common(initial,catalog);MilitaryState military;
 auto empty=query_military_actor_death(common,military,actor.id);check(empty.ok&&!empty.value,"alive false alone creates no death source");MilitaryUnitRecord unit;unit.dead={actor.id};military.military_units.push_back(unit);empty=query_military_actor_death(common,military,actor.id);check(empty.ok&&!empty.value,"current dead roster creates no death source");
 MilitaryCasualtyFact fact;fact.id="military:9";fact.battle_id="naval_round:8";fact.tick=6;MilitaryActorChange change;change.actor_id=actor.id;change.status="dead";fact.actor_changes={change};military.casualty_facts={fact};check(!query_military_actor_death(common,military,actor.id).ok,"orphan source rejected");common.state().facts.insert(fact.id,{fact.id,"military_casualties","military",{}});auto death=query_military_actor_death(common,military,actor.id);check(death.ok&&death.value&&death.value->actor_id==actor.id&&death.value->casualty_fact_id==fact.id&&death.value->battle_id==fact.battle_id&&death.value->tick==6,"returns exact original casualty id and source tick");
